using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    // The default resolver knows how to produce metadata for any type
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no casting needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

// Round-trip with the typed metadata
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Person p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {p}");

// 2. TryGetTypeInfo() — probe without throwing.
//    With DefaultJsonTypeInfoResolver every type succeeds:
if (options.TryGetTypeInfo(typeof(int), out JsonTypeInfo? intInfo))
    Console.WriteLine($"int metadata available: {intInfo!.Type.Name}");

//    With an empty resolver, nothing is resolvable:
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers → resolves nothing
};

if (restricted.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Person metadata found (unexpected)");
else
    Console.WriteLine("Person metadata NOT available — no exception thrown");

record Person(string Name, int Age);

